    global order_id
    order_id = identifier
    follow_ups.clear()
    tasks = BackgroundTasks()
    response = create_order(tasks)
    return {"response": response, "called_immediately": list(follow_ups), "registered": [[t.func.__name__, list(t.args)] for t in tasks.tasks]}

